// <<< w12:core-precache

const urlsToCache = [...CORE_PRECACHE, ...APP_PRECACHE];

const SCOPE_PATH = new URL('./', self.registration.scope).pathname; // e.g. '/repo/'
const APPS_PREFIX = SCOPE_PATH + 'js/apps/';

self.addEventListener('install', event => {
    event.waitUntil(
        caches.open(CACHE_NAME)
            .then(cache => cache.addAll(urlsToCache))
            .then(() => self.skipWaiting())
            .catch(() => self.skipWaiting())
    );
});

self.addEventListener('activate', event => {
    event.waitUntil(
        caches.keys().then(cacheNames => {
            return Promise.all(
                cacheNames.filter(name => name !== CACHE_NAME)
                    .map(name => caches.delete(name))
            );
        }).then(() => self.clients.claim())
    );
});

// ---------------------------------------------------------------------------
// Fetch routing
// ---------------------------------------------------------------------------

self.addEventListener('fetch', event => {
    const req = event.request;
    if (req.method !== 'GET') return;

    let url;
    try { url = new URL(req.url); } catch { return; }
    if (url.origin !== self.location.origin) return; // cross-origin: browser default

    if (url.pathname.startsWith(APPS_PREFIX)) {
        event.respondWith(handleAppRequest(req, url));
        return;
    }

    event.respondWith(defaultFetch(req));
});

// Network-first with a cache fallback (shell assets + builtin apps).
function defaultFetch(req) {
    return fetch(req)
        .then(response => {
            if (response && response.status === 200 && response.type === 'basic') {
                const clone = response.clone();
                caches.open(CACHE_NAME).then(cache => cache.put(req, clone)).catch(() => {});
            }
            return response;
        })
        .catch(() => caches.match(req));
}

function notFound() {
    return new Response('Not found', { status: 404, headers: { 'Content-Type': 'text/plain' } });
}

// /js/apps/<id>/<rest…>  → installed package (store) or shipped file (builtin)
async function handleAppRequest(req, url) {
    const rel = url.pathname.slice(APPS_PREFIX.length);
    const segments = rel.split('/').filter(Boolean);
    const id = segments[0];
    const rest = segments.slice(1);

    // Bare files directly under js/apps/ (e.g. registry.js) are shell assets.
    if (!id || rest.length === 0) return defaultFetch(req);

    if (APP_DIST[id] === 'builtin') return defaultFetch(req);

    // No OPFS tree at all means the legacy storage backend is in use (no
    // virtual filesystem the worker can read) — run store apps from the
    // shipped bundle.
    let tree = null;
    try { tree = await readTree(); } catch (e) { tree = null; }
    if (!tree) return defaultFetch(req);

    // Store app with packages available: an installed package is served from
    // the virtual filesystem. Code only becomes runnable once the package is
    // on disk, but static assets (icons, screenshots) still fall through to
    // the shipped bundle so catalogs can render an app before it is installed.
    try {
        const res = await serveFromTree(tree, id, rest);
        if (res) return res;
    } catch (e) { /* fall through */ }

    const last = rest[rest.length - 1] || '';
    if (/\.m?js$/i.test(last)) return notFound();
    return defaultFetch(req);
}

// ---------------------------------------------------------------------------
// Virtual package host (reads the vFS snapshot straight from OPFS)
// ---------------------------------------------------------------------------

let rootPromise = null;
function opfsRoot() {
    if (!rootPromise) rootPromise = navigator.storage.getDirectory();
    return rootPromise;
}

function splitPath(p) {
    return String(p).split('/').filter(Boolean);
}

async function opfsGetFile(parts) {
    try {
        let dir = await opfsRoot();
        for (let i = 0; i < parts.length - 1; i++) {
            dir = await dir.getDirectoryHandle(parts[i]);
        }
        const handle = await dir.getFileHandle(parts[parts.length - 1]);
        return await handle.getFile();
    } catch (e) {
        return null;
    }
}

// The tree snapshot is re-read whenever it may have changed. OPFS
// File.lastModified is not a dependable change signal across browsers, so
// instead of trusting a timestamp we keep the parse for a very short window
// (coalescing a burst of asset requests for one app) and otherwise read
// fresh — an install must be visible immediately, without a reload.
let treeCache = { at: 0, tree: null };
const TREE_TTL_MS = 250;
async function readTree() {
    const now = Date.now();
    if (treeCache.tree && now - treeCache.at < TREE_TTL_MS) return treeCache.tree;
    const file = await opfsGetFile(splitPath('w12/fs.json'));
    if (!file) return null;
    let tree;
    try { tree = JSON.parse(await file.text()); } catch (e) { return null; }
    treeCache = { at: now, tree };
    return tree;
}

// Active user is needed to locate per-user packages. The file is tiny and
// only written on boot / install, so read it per app request.
async function activeUser() {
    try {
        const file = await opfsGetFile(splitPath('w12/session.json'));
        if (file) {
            const parsed = JSON.parse(await file.text());
            if (parsed && parsed.userId) return parsed.userId;
        }
    } catch (e) { /* fall through */ }
    return 'default';
}

function resolveNode(tree, parts) {
    let node = tree;
    for (const part of parts) {
        if (!node || node.type !== 'folder' || !node.children) return null;
        node = node.children[part];
    }
    return node || null;
}

const MIME = {
    js: 'text/javascript', mjs: 'text/javascript', json: 'application/json',
    svg: 'image/svg+xml', css: 'text/css', html: 'text/html', htm: 'text/html',
    txt: 'text/plain', md: 'text/markdown', wasm: 'application/wasm',
    png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif',
    webp: 'image/webp', ico: 'image/x-icon', bmp: 'image/bmp',
    mp3: 'audio/mpeg', ogg: 'audio/ogg', wav: 'audio/wav', m4a: 'audio/mp4',
    mp4: 'video/mp4', webm: 'video/webm',
    ttf: 'font/ttf', otf: 'font/otf', woff: 'font/woff', woff2: 'font/woff2'
};

function mimeOf(name) {
    const ext = String(name || '').split('.').pop().toLowerCase();
    return MIME[ext] || 'application/octet-stream';
}

async function serveFromTree(tree, id, rest) {
    let node = resolveNode(tree, ['Program Files', id, ...rest]);
    if (!node) {
        const uid = await activeUser();
        node = resolveNode(tree, ['users', uid, 'AppData', 'Programs', id, ...rest]);
    }
    if (!node || node.type !== 'file') return null;

    const type = node.blobType || mimeOf(node.name);
    const headers = {
        'Content-Type': type,
        'Cache-Control': 'no-cache'
    };

    if (node.blobRef) {
        let file = await opfsGetFile(splitPath('w12/blobs/' + node.blobRef));
        if (!file) {
            // One retry: the OPFS worker may be mid-write (short-lived sync handle).
            await new Promise(r => setTimeout(r, 40));
            file = await opfsGetFile(splitPath('w12/blobs/' + node.blobRef));
        }
        if (!file) return null;
        return new Response(file, { headers });
    }

    return new Response(node.content ?? '', { headers });
}
